import{_ as t,H as e,f as r,i as o}from"./chunks/framework.CBmkDW73.js";const _=JSON.parse('{"title":"哲学","description":"","frontmatter":{},"headers":[],"relativePath":"ja/guide/philosophy.md","filePath":"ja/guide/philosophy.md"}'),d={name:"ja/guide/philosophy.md"};function i(h,a,s,n,l,p){return e(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="哲学" tabindex="-1">哲学 <a class="header-anchor" href="#哲学" aria-label="Permalink to &quot;哲学&quot;">​</a></h1><h2 id="意図で動かす、指示ではなく" tabindex="-1">意図で動かす、指示ではなく <a class="header-anchor" href="#意図で動かす、指示ではなく" aria-label="Permalink to &quot;意図で動かす、指示ではなく&quot;">​</a></h2><p>エージェントに達成すべきことと、完了がどのような形かを伝える。やり方はエージェントに任せる。</p><p>ステップバイステップの手順は、エージェントが賢くなるにつれて時代遅れになる。意図の宣言は常に有効だ — それらが伝えるのは<strong>何が重要か</strong>であって、<strong>どう実現するか</strong>ではない。</p><h2 id="価値のある規律にだけコストを払う" tabindex="-1">価値のある規律にだけコストを払う <a class="header-anchor" href="#価値のある規律にだけコストを払う" aria-label="Permalink to &quot;価値のある規律にだけコストを払う&quot;">​</a></h2><p>トリアージが決める。タイポ修正に仕様は不要。新しいシステムには必要だ。Praxisは複雑さに比例してオーバーヘッドを適用する。</p><table tabindex="0"><thead><tr><th>タスク</th><th>Praxisのコスト</th></tr></thead><tbody><tr><td>タイポを修正</td><td>~450トークン（ブートストラップのみ）</td></tr><tr><td>標準機能（設計→出荷）</td><td>~1,300トークン</td></tr><tr><td>複雑なタスク（全スキル）</td><td>~2,900トークン</td></tr></tbody></table><h2 id="スキルは短い" tabindex="-1">スキルは短い <a class="header-anchor" href="#スキルは短い" aria-label="Permalink to &quot;スキルは短い&quot;">​</a></h2><p>規則を表現するのに3,000トークンが必要なら、それはおそらく規則ではなくマニュアルだ。Praxisのスキルは平均約230トークン。</p><p>短いスキルはエージェントが完全に読み、確実に従い、AIの能力が進化しても維持しやすいフレームワークを保つ。</p><h2 id="仕様は事実であり、計画ではない" tabindex="-1">仕様は事実であり、計画ではない <a class="header-anchor" href="#仕様は事実であり、計画ではない" aria-label="Permalink to &quot;仕様は事実であり、計画ではない&quot;">​</a></h2><p>仕様は決定事項のリスト：契約、不変条件、失敗モード、テスト基準。ナラティブなし、理由付けなし、手順なし。計画は別物であり、マイルストーンのスタブ — スクリプトではない。</p><p>エージェントはドメイン知識をもたらす。Praxisは何を決定すべきかの構造を提供し、どう決定するかの指示ではない。</p>',13)])])}const u=t(d,[["render",i]]);export{_ as __pageData,u as default};
